306	=== CheckClerkLimit
307	/** Works out the move a status change makes. A clerk settling an OPEN claim whose due is above the
308	 *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
309	 *  sheet with no limit, and a steward, settle anything. Only a steward reviews a PENDING claim, and
310	 *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused.
311	 *  Before the limit is considered, settling or approving a claim with no proofs whose due is above the
312	 *  proof threshold is refused (see {@link CheckProofs}), so it never goes to PENDING. Opening, settling
313	 *  and voiding are refused to a role the sheet's permission matrix does not allow it. A SETTLED claim
314	 *  may be voided only by a steward, and only within {@link #VOID_SETTLED_DAYS} days of the sheet's today
315	 *  it was settled on (its status log's SETTLED date). */
316	public class CheckClerkLimit {
317	    /** How many days after settling a claim a steward may still void it. */
318	    static final int VOID_SETTLED_DAYS = 7;
319	    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
320	            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, ClaimLogStore log,
321	            Out<StatusMove> move)
322	            throws InvalidSheetException {
323	        ClaimStatus from = claim.getStatus();
324	        Role role = roles.find(claim.getSheetId(), input.user());
325	        boolean steward = role == Role.STEWARD;
326	        if (input.review()) {
327	            if (from != ClaimStatus.PENDING) {
328	                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
329	            }
330	            if (!steward) {
331	                throw new InvalidSheetException("Only a steward can approve or reject a claim");
332	            }
333	            CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
334	            move.set(new StatusMove(from, input.status()));
335	            return;
336	        }
337	        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
338	            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
339	        }
340	        refuseUnpermitted(input.status(), claim.getSheetId(), role, settings);
341	        if (from == ClaimStatus.SETTLED && input.status() == ClaimStatus.VOID) {
342	            refuseLateVoid(claim, steward, log, sheets);
343	        }
344	        if (from == ClaimStatus.DRAFT && input.status() == ClaimStatus.OPEN) {
345	            CheckProofs.refuseUnnoted(claim, settings, people, rates, sheets, claims);
346	        }
347	        CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
348	        move.set(new StatusMove(from, overLimit(input, claim, steward, settings, people, rates, sheets, claims)
349	                ? ClaimStatus.PENDING : input.status()));
350	    }
351	    /** Refuses voiding a SETTLED claim by anyone but a steward, or later than {@link #VOID_SETTLED_DAYS}
352	     *  days after it was settled. */
353	    static void refuseLateVoid(Claim claim, boolean steward, ClaimLogStore log, SheetStore sheets)
354	            throws InvalidSheetException {
355	        if (!steward) {
356	            throw new InvalidSheetException("Only a steward can void a SETTLED claim");
357	        }
358	        LocalDate settled = log.settledOn(claim);
359	        LocalDate today = sheets.today(claim.getSheetId());
360	        if (settled == null || today == null || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
361	            throw new InvalidSheetException("A SETTLED claim can be voided only within " + VOID_SETTLED_DAYS
362	                    + " days of settling it");
363	        }
364	    }
365	    /** Refuses opening, settling or voiding a claim by a role the sheet's permission matrix does not allow it. */
366	    static void refuseUnpermitted(ClaimStatus to, String sheetId, Role role, SettingStore settings)
367	            throws InvalidSheetException {
368	        String action = to == ClaimStatus.OPEN ? "open" : to == ClaimStatus.SETTLED ? "settle"
369	                : to == ClaimStatus.VOID ? "void" : null;
370	        if (action != null && !settings.allows(sheetId, action, role)) {
371	            throw new InvalidSheetException("A " + role.shown() + " may not " + action + " a claim");
372	        }
373	    }
374	    private static boolean overLimit(StatusInput input, Claim claim, boolean steward, SettingStore settings,
375	            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims) {
376	        if (input.status() != ClaimStatus.SETTLED || claim.getStatus() != ClaimStatus.OPEN || steward) {
377	            return false;
378	        }
379	        BigDecimal limit = settings.clerkLimit(claim.getSheetId());
380	        if (limit == null) {
381	            return false;
382	        }
383	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
384	        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
385	        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
386	        return due != null && due.compareTo(limit) > 0;
387	    }
388	}
389	=== CheckProofs
390	/** Refuses settling an OPEN claim, or approving a PENDING one, while it has no proofs and its due is above
391	 *  the proof threshold in force on its date (its person's grade's then when one is set, else the sheet's). A sheet with no threshold then, and a claim whose due is n/a,
392	 *  need no proof. */
393	final class CheckProofs {
394	    private CheckProofs() {
395	    }
396	    static void refuseUnproved(StatusInput input, Claim claim, SettingStore settings, PersonStore people,
397	            RateStore rates, SheetStore sheets, ClaimStore claims) throws InvalidSheetException {
398	        ClaimStatus from = claim.getStatus();
399	        if (input.status() != ClaimStatus.SETTLED || (from != ClaimStatus.OPEN && from != ClaimStatus.PENDING)
400	                || claim.getProofs() > 0) {
401	            return;
402	        }
403	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
404	        String grade = person == null ? null : person.gradeOn(claim.getDate());
405	        BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), grade, claim.getDate());
406	        if (threshold == null) {
407	            return;
408	        }
409	        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), grade, claim.getDate());
410	        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
411	        if (due != null && due.compareTo(threshold) > 0) {
412	            throw new InvalidSheetException("A claim due above the proof threshold of " + threshold.setScale(2)
413	                    + " needs a proof before it can be " + (input.review() ? "approved" : "settled"));
414	        }
415	    }
416	    /** Refuses opening a DRAFT claim with an empty note while its due is above the note threshold in force on
417	     *  its date. A sheet with no threshold then, and a claim whose due is n/a, need no note. */
418	    static void refuseUnnoted(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
419	            SheetStore sheets, ClaimStore claims) throws InvalidSheetException {
420	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
421	            return;
422	        }
423	        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
424	        if (threshold == null) {
425	            return;
426	        }
427	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
428	        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
429	        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
430	        if (due != null && due.compareTo(threshold) > 0) {
431	            throw new InvalidSheetException("A claim due above the note threshold of " + threshold.setScale(2)
432	                    + " needs a note before it can be opened");
433	        }
434	    }
435	}
436	=== ApplyStatus
437	/** Moves the claim to the new status, refusing a change its current status does not allow. Opening
438	 *  gives the claim its next number (see {@link Numbering}) and records who opened it; a voided claim keeps its number, which is never reused. Settling fixes its due at its person's
439	 *  grade rate in force on the claim's date, rounded as the sheet's policy date has it (none when no rate of the grade applies then),
440	 *  or at the figure its person's last statement bound it to, plus the late charge it has then, and at least the sheet's floor (frozen in).
441	 *  A clerk's settle above the clerk limit makes it PENDING instead (see {@link CheckClerkLimit}); a steward's
442	 *  approval settles a PENDING claim, frozen then at its live figure (a statement does not bind it while
443	 *  PENDING), and a rejection moves it back to OPEN, bound again by its person's last statement if that included it.
444	 *  The user who opened a claim, or who last edited it, may not settle or approve it, and a claim deferred on the sheet's today may not be settled.
445	 *  While the sheet has void reasons, a void needs one of them (the input's reason), kept on the claim. */
446	public class ApplyStatus {
447	    public void apply(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, ClaimStore store, PersonStore people,
448	            RateStore rates, SettingStore settings, SheetStore sheets, PeriodStore periods,
449	            VoidReasonStore voidReasons, Out<StatusChange> change)
450	            throws InvalidSheetException {
451	        ClaimStatus from = move.from();
452	        ClaimStatus to = move.to();
453	        if (input.status() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
454	                && claim.getOpenedBy().equals(input.user())) {
455	            throw new InvalidSheetException("The user who opened a claim cannot "
456	                    + (input.review() ? "approve" : "settle") + " it");
457	        }
458	        if (input.status() == ClaimStatus.SETTLED && claim.getEditedBy() != null
459	                && claim.getEditedBy().equals(input.user())) {
460	            throw new InvalidSheetException("The user who last edited a claim cannot "
461	                    + (input.review() ? "approve" : "settle") + " it");
462	        }
463	        if (input.status() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
464	            throw new InvalidSheetException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
465	        }
466	        String voidReason = null;
467	        if (to == ClaimStatus.VOID) {
468	            List<String> reasons = voidReasons.list(claim.getSheetId());
469	            if (!reasons.isEmpty()) {
470	                if (input.reason().isEmpty()) {
471	                    throw new InvalidSheetException("A void needs a reason from the sheet's list");
472	                }
473	                if (!reasons.contains(input.reason())) {
474	                    throw new InvalidSheetException(input.reason() + " is not a void reason on the sheet");
475	                }
476	                voidReason = input.reason();
477	            }
478	        }
479	        if (!from.canBecome(to) || !store.move(claim, from, to)) {
480	            throw new InvalidSheetException("A " + from + " claim cannot become " + to);
481	        }
482	        // The due to freeze is worked out while the claim is still OPEN or PENDING, so it takes its late charge in.
483	        BigDecimal settledDue = null;
484	        if (to == ClaimStatus.SETTLED) {
485	            Person person = people.find(claim.getSheetId(), claim.getPersonId());
486	            BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
487	            settledDue = Lateness.of(claim.getSheetId(), settings, sheets, store, people).due(claim, pct);
488	        }
489	        claim.setStatus(to);
490	        if (to == ClaimStatus.VOID) {
491	            claim.setVoidReason(voidReason);
492	        }
493	        if (from == ClaimStatus.DRAFT && to == ClaimStatus.OPEN) {
494	            claim.setNumber(Numbering.next(claim.getSheetId(), claim.getDueBy(), store, settings, sheets, periods));
495	            claim.setOpenedBy(input.user());
496	        }
497	        if (to == ClaimStatus.SETTLED) {
498	            claim.setSettledDue(settledDue);
499	        }
500	        change.set(new StatusChange(claim.getNumber()));
501	    }
502	}
