505	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody StatusRequest request, Out<StatusInput> body, RoleStore roles) throws InvalidSheetException {
506	        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
507	        String status = request == null || request.status() == null ? "" : request.status().trim();
508	        ClaimStatus to;
