515	        String reason = request.reason() == null ? "" : request.reason().trim();
516	        if (review && to != ClaimStatus.SETTLED && to != ClaimStatus.OPEN) {
517	            throw new InvalidSheetException("A review approves or rejects a claim");
518	        }
519	        if (review && to == ClaimStatus.OPEN && reason.isEmpty()) {
520	            throw new InvalidSheetException("A rejection needs a reason");
521	        }
522	        body.set(new StatusInput(to, request.user(), review, reason));
