526	public class ValidateClaim {
527	    /** A number with up to two decimals; negative for a correction. */
528	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
529	    /** A claim number: the sheet-wide 1, 2, ... or <period>-<n> / X-<n>. */
530	    private static final Pattern NUMBER = Pattern.compile("\\S{1,255}");
531	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request,
532	            SettingStore settings, Out<ClaimInput> body, RoleStore roles) throws InvalidSheetException {
533	        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
534	        body.set(check(sheetId, request, settings));
535	    }
536	    /** The claim form's rules on a typed claim, before anything is stored: the claim as it would be stored
537	     *  (a blank date is the entry date while it is set, else the sheet's today). */
538	    static ClaimInput check(String sheetId, ClaimRequest request, SettingStore settings) throws InvalidSheetException {
539	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
540	        if (!AMOUNT.matcher(amount).matches()) {
541	            throw new InvalidSheetException("The amount must be a number with up to two decimals");
542	        }
543	        String dateText = request.date() == null ? "" : request.date().trim();
544	        LocalDate date;
545	        try {
546	            date = dateText.isEmpty() ? settings.claimDate(sheetId.trim()) : LocalDate.parse(dateText);
547	        } catch (DateTimeParseException e) {
548	            throw new InvalidSheetException("Not a date: " + dateText);
549	        }
550	        String note = request.note() == null ? "" : request.note().trim();
551	        BigDecimal value = new BigDecimal(amount).setScale(2);
552	        String correctsText = request.corrects() == null ? "" : request.corrects().trim();
553	        String corrects = null;
554	        if (value.signum() < 0) {
555	            if (!NUMBER.matcher(correctsText).matches()) {
556	                throw new InvalidSheetException("A negative amount must name the number of the settled claim it corrects");
557	            }
558	            corrects = correctsText;
559	        } else if (!correctsText.isEmpty()) {
560	            throw new InvalidSheetException("Only a negative amount corrects a claim");
561	        }
562	        String ref = request.ref() == null ? "" : request.ref().trim();
563	        return new ClaimInput(value, date, note, request.user(), corrects, ref.isEmpty() ? null : ref,
564	                Tags.normalise(request.tags()));
565	    }
566	}
