568	/** Adds the claim (a late entry when the period its due-by falls in is soft-closed), due by the business day its person's own terms (else the terms of their grade in force on
569	 *  that date, else the sheet's terms in force then) after its date, skipping weekends and the sheet's holidays, fixed now, and logs it as DRAFT by the user at its due then. */
570	public class SaveClaimAdded {
571	    public void save(@Val ClaimInput input, @Val Person person, ClaimStore store, SettingStore settings,
572	            ClaimLogStore log, PeriodStore periods, HolidayStore holidays, Out<Claim> claim) {
573	        claim.set(add(input, person, store, settings, log, periods, holidays));
574	    }
575	    static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings, ClaimLogStore log,
576	            PeriodStore periods, HolidayStore holidays) {
577	        int terms = termsOf(person, input.date(), settings);
578	        LocalDate dueBy = holidays.businessDaysAfter(person.getSheetId(), input.date(), terms);
579	        Claim added = store.add(person.getSheetId(), person.getId(), input.amount(), input.date(), input.note(),
580	                input.corrects(), dueBy, terms, input.ref(), input.tags());
581	        if (periods.softOn(person.getSheetId(), dueBy)) {
582	            store.markLateEntry(added);
583	        }
584	        log.record(added, input.user());
585	        return added;
586	    }
587	    /** The terms a claim of the person dated {@code date} is due by: their own, else their grade's in force
588	     *  on the date, else the sheet's then. */
589	    static int termsOf(Person person, LocalDate date, SettingStore settings) {
590	        return person.getTerms() != null ? person.getTerms()
591	                : settings.terms(person.getSheetId(), person.gradeOn(date), date);
592	    }
