            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
    private static boolean closed(PeriodStore periods, Claim claim) {
        try {
            ClaimPeriods.refuseClosed(periods, claim.getSheetId(), claim.getDueBy());
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
