131	/** Splits the amount off the OPEN claim, which keeps the rest unbound from any statement figure, into a new
132	 *  OPEN claim of the same date and note, numbered next in the period of its own due-by (see {@link Numbering}), opened by the user, due by
133	 *  the business day its person's own terms (else their grade's in force on that date, else the sheet's then) after its date, fixed
134	 *  now (a late entry when the period that due-by falls in is soft-closed), and logged as OPEN by the user. Refused when another user moved the claim on first. */
135	public class ApplySplit {
136	    public void apply(@Val SplitInput input, @Val Claim claim, ClaimStore store, PersonStore people, SettingStore settings,
137	            SheetStore sheets, PeriodStore periods, ClaimLogStore log, HolidayStore holidays,
138	            Out<Split> split) throws InvalidSheetException {
139	        if (!store.shrink(claim, claim.getAmount().subtract(input.amount()))) {
140	            throw new InvalidSheetException("Only an OPEN claim can be split");
141	        }
142	        String sheetId = claim.getSheetId();
143	        Person person = people.find(sheetId, claim.getPersonId());
144	        int terms = SaveClaimAdded.termsOf(person, claim.getDate(), settings);
145	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
146	        String number = Numbering.next(sheetId, dueBy, store, settings, sheets, periods);
147	        Claim into = store.addSplit(claim, input.amount(), number, input.user(), dueBy, terms);
148	        if (periods.softOn(sheetId, dueBy)) {
149	            store.markLateEntry(into);
150	        }
151	        log.record(into, input.user());
152	        split.set(new Split(into));
153	    }
