299	/** Moves each selected claim to the chosen person, in list order: its people in the order they were added, a
300	 *  person's claims newest first. Each goes through the very steps of a single move by the user (role, period,
301	 *  status, correction and retirement checks, then store and audit as CLAIM_REASSIGNED with its rollup lines). A
302	 *  claim that is not on the sheet, or that a single move would refuse, is refused and left as it is. */
303	public class ReassignClaims {
304	    public void reassign(@PathVariable("sheetId") String sheetId, @Val BulkReassignInput input, ClaimStore store,
305	            PersonStore people, PeriodStore periods, SettingStore settings, RoleStore roles, RollupService rollups,
306	            Audit audit, Out<BulkReassignResult> result) {
307	        String sheet = sheetId.trim();
308	        Map<Long, Integer> personOrder = new HashMap<>();
309	        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
310	        Map<Long, Integer> listed = new HashMap<>();
311	        for (Claim claim : store.list(sheet)) {
312	            listed.put(claim.getId(), listed.size());
313	        }
314	        for (Person person : people.list(sheet)) {
315	            personOrder.put(person.getId(), personOrder.size());
316	        }
317	        int refused = 0;
318	        List<Claim> selected = new ArrayList<>();
319	        for (Long id : input.claimIds()) {
320	            Claim claim = id == null ? null : store.find(sheet, id);
321	            if (claim == null) {
322	                refused++;
323	            } else {
324	                selected.add(claim);
325	            }
326	        }
327	        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
328	                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
329	        ReassignInput move = new ReassignInput(input.to(), input.user());
330	        int reassigned = 0;
331	        for (Claim claim : selected) {
332	            try {
333	                roles.refuseChange(sheet, input.user());
334	                new CheckClaimPeriod().check(claim, periods);
335	                Reassignment reassignment = CheckReassign.refuse(move, claim, roles, people, settings, true);
336	                Rollup before = rollups.snapshot(sheet);
337	                new ApplyReassign().apply(claim, reassignment, store);
338	                new AuditClaimReassigned().audit(move, claim, reassignment, before, audit, rollups);
339	                reassigned++;
340	            } catch (InvalidSheetException e) {
341	                refused++;
342	            }
343	        }
344	        result.set(new BulkReassignResult(reassigned, refused));
345	    }
346	}
347	=== SettleClaims
348	/** Settles each selected claim, in list order: its people in the order they were added, a person's
349	 *  claims newest first. Each goes through the very steps of a single settle by the user (period,
350	 *  clerk limit, opened-by, edited-by and status checks, then store, log and audit), so a clerk's settle above
351	 *  the clerk limit sends it to PENDING, which counts as settled. A claim that is not on the sheet,
352	 *  or that a single settle would refuse (every claim on an archived sheet), is refused.
353	 *  All or nothing: when any is refused, none is settled, every one counts as refused and nothing is
354	 *  stored or audited. Otherwise the bulk settle takes the sheet's next batch, each settled claim records
355	 *  it, and after the claims' own records BATCH_SETTLED sheet=<id> by=<user> batch=<n> count=<claims>
356	 *  total=<the frozen figures of those SETTLED, added up> is written. */
357	public class SettleClaims {
358	    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimStore store,
359	            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
360	            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, WatchStore watches,
361	            VoidReasonStore voidReasons, PlatformTransactionManager transactions,
362	            Out<BulkSettleResult> result) {
363	        String sheet = sheetId.trim();
364	        Map<Long, Integer> personOrder = new HashMap<>();
365	        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
366	        Map<Long, Integer> listed = new HashMap<>();
367	        for (Claim claim : store.list(sheet)) {
368	            listed.put(claim.getId(), listed.size());
369	        }
370	        for (Person person : people.list(sheet)) {
371	            personOrder.put(person.getId(), personOrder.size());
372	        }
373	        int refused = 0;
374	        List<Claim> selected = new ArrayList<>();
375	        for (Long id : input.claimIds()) {
376	            Claim claim = id == null ? null : store.find(sheet, id);
377	            if (claim == null) {
378	                refused++;
379	            } else {
380	                selected.add(claim);
381	            }
382	        }
383	        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
384	                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
385	        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
386	        int all = input.claimIds().size();
387	        if (refused > 0) {
388	            result.set(new BulkSettleResult(0, all));
389	            return;
390	        }
391	        // All or nothing: the claims are settled in a nested transaction, their audit records held back,
392	        // and the first refusal rolls every one of them back and drops the records.
393	        TransactionTemplate nested = new TransactionTemplate(transactions);
394	        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
395	        audit.hold();
396	        boolean done = false;
397	        try {
398	            done = Boolean.TRUE.equals(nested.execute(tx -> {
399	                long batch = store.nextBatch(sheet);
400	                BigDecimal total = BigDecimal.ZERO;
401	                for (Claim claim : selected) {
402	                    try {
403	                        sheets.refuseArchived(sheet);
404	                        new CheckClaimPeriod().check(claim, periods);
405	                        StatusMove[] move = new StatusMove[1];
406	                        new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, log,
407	                                m -> move[0] = m);
408	                        Rollup before = rollups.snapshot(sheet);
409	                        StatusChange[] change = new StatusChange[1];
410	                        new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods,
411	                                voidReasons, c -> change[0] = c);
412	                        new SaveClaim().save(status, claim, store, log);
413	                        store.markBatch(claim, batch);
414	                        new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups,
415	                                watches);
416	                        if (move[0].to() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
417	                            total = total.add(claim.getSettledDue());
418	                        }
419	                    } catch (InvalidSheetException e) {
420	                        tx.setRollbackOnly();
421	                        return false;
422	                    }
423	                }
424	                audit.record("BATCH_SETTLED sheet=" + sheet + " by=" + input.user() + " batch=" + batch + " count="
425	                        + selected.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
426	                return true;
427	            }));
428	        } finally {
429	            if (done) {
430	                audit.release();
431	            } else {
432	                audit.discard();
433	            }
434	        }
435	        result.set(done ? new BulkSettleResult(selected.size(), 0) : new BulkSettleResult(0, all));
436	    }
437	}
