453	        Map<Long, Integer> listed = new HashMap<>();
454	        for (Claim claim : store.list(sheet)) {
455	            listed.put(claim.getId(), listed.size());
456	        }
457	        for (Person person : people.list(sheet)) {
458	            personOrder.put(person.getId(), personOrder.size());
459	            persons.put(person.getId(), person);
460	        }
461	        int refused = 0;
462	        List<Claim> selected = new ArrayList<>();
463	        for (Long id : input.claimIds()) {
464	            Claim claim = id == null ? null : store.find(sheet, id);
465	            if (claim == null) {
