273	public class ValidateSetting {
274	    /** 0.00 or more, with up to two decimals. */
275	    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
276	    /** A whole number of days, 0 or more. */
277	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
278	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingRequest request, Out<SettingInput> body, RoleStore roles) throws InvalidSheetException {
279	        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
280	        String key = request == null || request.key() == null ? "" : request.key().trim();
281	        boolean floor = SettingStore.FLOOR.equals(key);
282	        boolean terms = SettingStore.TERMS.equals(key);
283	        boolean gradeTerms = key.startsWith(SettingStore.TERMS_PREFIX)
284	                && SettingStore.GRADES.contains(key.substring(SettingStore.TERMS_PREFIX.length()));
285	        boolean gradeGrace = SettingStore.isGradeGrace(key);
286	        boolean late = SettingStore.LATE_PCT.equals(key);
287	        boolean numbering = SettingStore.PERIOD_NUMBERING_FROM.equals(key);
288	        boolean entry = SettingStore.ENTRY_DATE.equals(key);
289	        boolean dated = SettingStore.POLICY_DATE.equals(key) || numbering || entry;
290	        boolean cap = SettingStore.CAP.equals(key);
291	        boolean gradeProof = SettingStore.isGradeProofThreshold(key);
292	        boolean proof = SettingStore.PROOF_THRESHOLD.equals(key) || gradeProof;
293	        boolean note = SettingStore.NOTE_THRESHOLD.equals(key);
294	        if (SettingStore.GRACE_DAYS.equals(key)) {
295	            String value = request.value() == null ? "" : request.value().trim();
296	            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
297	                throw new InvalidSheetException("The grace days must be a whole number of days, 0 or more, or blank");
298	            }
299	            body.set(new SettingInput(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null,
300	                    request.user()));
301	            return;
302	        }
303	        if (key.startsWith(SettingStore.PERM_PREFIX)
304	                && SettingStore.PERM_ACTIONS.contains(key.substring(SettingStore.PERM_PREFIX.length()))) {
305	            body.set(new SettingInput(key, perm(request.value()), null, request.user()));
306	            return;
307	        }
308	        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !proof && !note && !floor && !terms && !gradeTerms && !gradeGrace && !late && !dated) {
309	            throw new InvalidSheetException("Not a setting: " + key);
310	        }
311	        String value = request.value() == null ? "" : request.value().trim();
312	        String fromValue = request.from() == null ? "" : request.from().trim();
313	        LocalDate from = null;
314	        if (!dated && !fromValue.isEmpty()) {
315	            try {
316	                from = LocalDate.parse(fromValue);
317	            } catch (DateTimeParseException e) {
318	                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
319	            }
320	        }
321	        if (dated) {
322	            if (value.isEmpty()) {
323	                body.set(new SettingInput(key, null, from, request.user()));
324	                return;
325	            }
326	            try {
327	                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
328	            } catch (DateTimeParseException e) {
329	                throw new InvalidSheetException((numbering ? "The period numbering from" : entry ? "The entry date" : "The policy date")
330	                        + " must be a date (YYYY-MM-DD), or blank");
331	            }
332	            return;
333	        }
334	        if (gradeGrace) {
335	            if (value.isEmpty()) {
336	                body.set(new SettingInput(key, null, from, request.user()));
337	                return;
338	            }
339	            if (!DAYS.matcher(value).matches()) {
340	                throw new InvalidSheetException("The grade's grace days must be a whole number of days, 0 or more, or blank");
341	            }
342	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
343	            return;
344	        }
345	        if (gradeTerms) {
346	            if (value.isEmpty()) {
347	                body.set(new SettingInput(key, null, from, request.user()));
348	                return;
349	            }
350	            if (!DAYS.matcher(value).matches()) {
351	                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
352	            }
353	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
354	            return;
355	        }
356	        if (terms) {
357	            if (value.isEmpty()) {
358	                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), from, request.user()));
359	                return;
360	            }
361	            if (!DAYS.matcher(value).matches()) {
362	                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
363	            }
364	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
365	            return;
366	        }
367	        if (value.isEmpty() && floor) {
368	            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), from, request.user()));
369	            return;
370	        }
371	        if (value.isEmpty() && late) {
372	            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
373	            return;
374	        }
375	        if (value.isEmpty()) {
376	            body.set(new SettingInput(key, null, from, request.user()));
377	            return;
378	        }
379	        if (!LIMIT.matcher(value).matches()) {
380	            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
381	                    : late ? "The late percent must be 0.00 or more with up to two decimals"
382	                    : gradeProof ? "The grade's proof threshold must be 0.00 or more with up to two decimals, or blank"
383	                    : proof ? "The proof threshold must be 0.00 or more with up to two decimals, or blank"
384	                    : note ? "The note threshold must be 0.00 or more with up to two decimals, or blank"
385	                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
386	                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
387	        }
388	        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
389	    }
390	    /** The roles listed, comma separated without spaces, or null when blank (the standing rule). */
391	    private static String perm(String raw) throws InvalidSheetException {
392	        String value = raw == null ? "" : raw.trim();
393	        if (value.isEmpty()) {
394	            return null;
395	        }
396	        List<String> roles = new ArrayList<>();
397	        for (String part : value.split(",")) {
398	            String role = part.trim();
399	            if (Role.of(role) == null || Role.of(role) == Role.VIEWER) {
400	                throw new InvalidSheetException("A permission lists roles (clerk, steward), comma separated, or is blank");
401	            }
402	            if (!roles.contains(role)) {
403	                roles.add(role);
404	            }
405	        }
406	        return String.join(",", roles);
407	    }
