467	/** Takes a statement of the person on the sheet's today: their due-total (the sum of the figures of
468	 *  their claims that count; n/a when their grade in force today has no rate today and no counting claim
469	 *  keeps a fixed figure or a figure at another grade, the one in force on its date), binding each counting claim to its figure now (its rate figure, not floored, when not fixed) and unbinding the rest. A settled
470	 *  claim keeps its fixed figure. The due-total includes the late charges of overdue claims and the floor, but a
471	 *  claim is bound to its figure without its charge or floor, which keeps following the sheet's today. The
472	 *  due-total is at most the sheet's cap.
473	 *  <p>
474	 *  Taken as of a date (on or before the sheet's today), everything is as it stood at the end of that date
475	 *  (see {@link net.officefloor.hq.app.history.History}): their claims that counted then are bound to their
476	 *  figures then, and the date stands in for the sheet's today in every figure (grade and rate in force, floor,
477	 *  late charges, holds, retirement, cap); every other claim of theirs is unbound. The statement is dated that
478	 *  date. Refused when the date is after the sheet's today, or the person was not on the sheet then. */
479	public class TakeStatement {
480	    public void take(@Val StatementRequest request, @Val Person person, ClaimStore claims, RateStore rates,
481	            SheetStore sheets, SettingStore settings, PersonStore people, StatementStore statements,
482	            Out<Statement> statementOut) throws InvalidSheetException {
483	        String sheetId = person.getSheetId();
484	        LocalDate today = sheets.today(sheetId);
485	        LocalDate asOf = request.asOfDate();
486	        if (asOf != null && asOf.isAfter(today)) {
487	            throw new InvalidSheetException("The statement date is after the sheet's today");
488	        }
489	        // Locked, so a status change or another statement made at once waits for this one.
490	        List<Claim> bound = claims.listForUpdate(sheetId, person.getId());
491	        // What the figures follow: the store as it is now, or as it stood at the end of the date.
492	        LocalDate on = today;
493	        Person then = person;
494	        List<Claim> all;
495	        Map<Long, Claim> was = new HashMap<>();
496	        if (asOf == null) {
497	            all = claims.list(sheetId);
498	            bound.forEach(claim -> was.put(claim.getId(), claim));
499	        } else {
500	            on = asOf;
501	            then = people.findAsOf(sheetId, person.getId(), asOf);
502	            if (then == null) {
503	                throw new InvalidSheetException("The person was not on the sheet on " + asOf);
504	            }
505	            rates = rates.asOf(asOf);
506	            settings = settings.asOf(asOf);
507	            all = claims.listAsOf(sheetId, asOf);
508	            all.stream().filter(claim -> claim.getPersonId() == person.getId()).forEach(claim -> was.put(claim.getId(), claim));
509	        }
510	        LocalDate policy = settings.policyDate(sheetId);
511	        Rounding rounding = new Rounding(policy != null ? policy : on, all);
512	        Person whose = then;
513	        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), on, rounding,
514	                Lateness.graced(settings.graces(sheetId), id -> id == whose.getId() ? whose : null));
515	        BigDecimal total = BigDecimal.ZERO.setScale(2);
516	        boolean fixed = false;
517	        int counted = 0;
518	        for (Claim live : bound) {
519	            // The claim as it stood then (itself when taken now); null when it was not theirs then.
520	            Claim claim = was.get(live.getId());
521	            // An OPEN (or PENDING) claim dated within a hold counts in no live total unless a statement bound
522	            // it, so a statement neither counts nor binds it; one it bound before stays counted. A deferred
523	            // claim counts in no total until the sheet's today reaches its date: a statement leaves it unbound.
524	            boolean counts = claim != null && RollupService.counts(claim, then, on);
525	            BigDecimal figure = null;
526	            boolean na = false;
527	            if (counts) {
528	                figure = ClaimFigure.of(claim, rates.find(sheetId, then.gradeOn(claim.getDate()), claim.getDate()), rounding);
529	                counted++;
530	                if (figure != null) {
531	                    total = total.add(lateness.dueOf(claim, figure));
532	                }
533	                // A figure at a grade other than the one in force today, or at a rate that ended before
534	                // today, does not hang on today's grade's rate.
535	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
536	                        || (figure != null && (!then.gradeOn(claim.getDate()).equals(then.gradeOn(on))
537	                                || rates.endsBefore(sheetId, then.gradeOn(claim.getDate()), claim.getDate(), on)));
538	                // A claim whose rate ended before its date is bound to n/a, so a later rate leaves it so.
539	                na = figure == null && (claim.isBound()
540	                        || (claim.getSettledDue() == null && rates.ended(sheetId, then.gradeOn(claim.getDate()), claim.getDate())));
541	            }
542	            live.setStated(counts);
543	            live.setStatedDue(figure);
544	            live.setStatedNa(na);
545	            claims.bind(live);
546	        }
547	        boolean na = rates.find(sheetId, then.gradeOn(on), on) == null && !fixed;
548	        Statement statement = new Statement(person.getId(), on,
549	                na ? null : SettingStore.capped(total, settings.cap(sheetId)), counted);
550	        statements.add(sheetId, statement, request.user());
551	        statementOut.set(statement);
552	    }
553	}
