555	/** Cancels the person's last statement: removes it and unbinds each of their claims, so they follow their
556	 *  live figures again. A figure bound by the statement before it is not restored. Refused when the person
557	 *  has no statement. */
558	public class CancelStatement {
559	    public void cancel(@Val Person person, ClaimStore claims, StatementStore statements,
560	            Out<Statement> cancelledOut) throws InvalidSheetException {
561	        String sheetId = person.getSheetId();
562	        // Locked, so a statement or status change made at once waits for this one.
563	        var bound = claims.listForUpdate(sheetId, person.getId());
564	        Statement last = statements.removeLast(sheetId, person.getId());
565	        if (last == null) {
566	            throw new InvalidSheetException("No statement to cancel");
567	        }
568	        for (Claim claim : bound) {
569	            if (claim.isStated() || claim.getStatedDue() != null || claim.isStatedNa()) {
570	                claim.setStated(false);
571	                claim.setStatedDue(null);
572	                claim.setStatedNa(false);
573	                claims.bind(claim);
574	            }
575	        }
576	        cancelledOut.set(last);
577	    }
